// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LionsLounge {
    function owner() external view returns (address);
    function blacklistAddress(address _address, bool _value) external;
    function isBlacklisted(address _address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the already deployed contract
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, we need to get the owner address
        // We can read it from storage or we can impersonate the deployer
        // Since the contract was deployed by msg.sender in constructor, we can impersonate that

        // Get the owner address
        address owner = LionsLounge(TARGET).owner();

        // Impersonate the owner (deployer)
        vm.startPrank(owner);

        // Call blacklistAddress on the victim
        LionsLounge(TARGET).blacklistAddress(victim, true);

        vm.stopPrank();

        // Verify the victim is blacklisted
        bool isBlacklisted = LionsLounge(TARGET).isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
